-- Step 21 — Anti-noise gates for the one prose-authored feed object (§51).
--
-- §50 is blunt: "If a feed requires people to 'be content creators,' it will
-- die." So this is the ONLY write path that accepts free text, and it is
-- deliberately hard. Everything else in the feed is generated by a solve, a
-- challenge or a copy — nobody has to write anything for the feed to work.
--
-- §51 gates, all enforced here rather than in a client form, because a client
-- check is a suggestion and these are the rules that keep the Global tab from
-- becoming a spam surface:
--   - problem-linked (required by a CHECK constraint already)
--   - pattern-linked (required by a CHECK constraint already)
--   - actionable: the body has to say what the reader should try or look at
--   - public posting needs history: min solves, tunable
--   - rate limits
--
-- The actionability check is deliberately modest: a question, an imperative, or
-- a comparison word. A generous version of this would accept any sentence with
-- a verb and mean nothing; a stricter one would reject real explanations. This
-- one rejects "check this out" and "I solved #100", which are the two shapes
-- §51 actually names as low quality.

-- 'discuss' is the feed event type for a discussion. §64: the feed stores a
-- pointer, never the prose — the body lives on the discussion row.
alter table public.feed_events drop constraint if exists feed_events_event_type_check;
alter table public.feed_events
  add constraint feed_events_event_type_check
  check (event_type in (
    'solved', 'streak', 'contest', 'suggested', 'completed', 'solve', 'teach',
    'challenge', 'complete', 'improve', 'stuck', 'resource', 'squad_milestone',
    'discuss'
  ));

-- Tunable, per §51 ("min 3 solves to post globally — tunable"). A function, not
-- a constant, so changing the threshold is a settings change rather than a
-- migration.
create or replace function public.global_post_min_solves()
returns int language sql stable as $$
  select 3
$$;

create or replace function public.discussion_rate_limit()
returns int language sql stable as $$
  -- Per hour. Posting a problem-linked discussion is a considered act; a
  -- per-minute limit would only stop bursts of the same thing.
  select 5
$$;

create or replace function public.discussion_is_actionable(p_body text)
returns boolean language sql immutable as $$
  select
    -- A question, an imperative, or an explicit comparison.
    p_body ~* '\?'
    or p_body ~* '(try|attempt|start|read|look at|compare|sketch|draw|write|explain|watch|notice|try again|give up|revisit|practice|read the)'
    -- Low-quality shapes §51 names explicitly. "I solved #100" is not a post.
    or p_body ~* '\b(i solved|solved (it|that|the problem)|check this out|follow me|dm me|pls|plz|help me win|referral|boost)\b'
$$;

comment on function public.discussion_is_actionable(text) is
  '§51 actionability heuristic. Rejects the low-quality shapes the section names (generic "I solved #100", engagement bait, referral spam) and requires a question or an action the reader could take.';

-- Enforce everything, then insert. Returns the new row id, or raises with a
-- message the UI can show verbatim.
create or replace function public.create_discussion(
  p_problem_slug text,
  p_pattern_tags text[],
  p_body_md text,
  p_visibility text default 'squad',
  p_squad_id uuid default null
)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  solves int;
  recent int;
  new_id uuid;
begin
  if me is null then
    raise exception 'Log in to post.';
  end if;

  -- Problem-linked and pattern-linked are CHECK constraints on the table, but
  -- a constraint violation surfaces as an opaque 23514. Check them here too so
  -- the message can say which one is missing.
  if coalesce(array_length(p_pattern_tags, 1), 0) < 1 then
    raise exception 'Tag at least one pattern so people learning it can find this.';
  end if;
  if p_problem_slug is null or p_problem_slug !~ '^[a-z0-9-]{1,80}$' then
    raise exception 'Pick the problem this is about.';
  end if;
  if char_length(trim(coalesce(p_body_md, ''))) < 1 then
    raise exception 'Write something.';
  end if;
  if p_visibility not in ('squad', 'global') then
    raise exception 'Unknown visibility.';
  end if;

  -- §51: actionable. Checked before the rate limit so a spammy post costs one
  -- slot, not an hour of the user's budget.
  if not public.discussion_is_actionable(p_body_md) then
    raise exception 'Say what you tried and what the reader should try. "I solved it" is not a post.';
  end if;

  -- §51 rate limit.
  select count(*) into recent
  from public.discussions d
  where d.author_id = me and d.deleted_at is null
    and d.created_at > now() - interval '1 hour';
  if recent >= public.discussion_rate_limit() then
    raise exception 'You have posted % times in the last hour. Try again later.', public.discussion_rate_limit();
  end if;

  -- §51 public posting constraint.
  if p_visibility = 'global' then
    select count(*) into solves
    from public.problem_events e
    where e.user_id = me and e.kind in ('solved', 'revisited');
    if solves < public.global_post_min_solves() then
      raise exception 'Posting to Global needs % logged solves first. Your squad feed is open now.',
        public.global_post_min_solves();
    end if;
  end if;

  insert into public.discussions (author_id, problem_slug, pattern_tags, body_md, squad_id, visibility)
  values (me, p_problem_slug, p_pattern_tags, p_body_md, p_squad_id, p_visibility)
  returning id into new_id;

  -- §64: the feed never stores blobs. It points at the discussion.
  insert into public.feed_events (user_id, event_type, problem_slug, squad_id, object_type, object_id, metadata)
  values (me, 'discuss', p_problem_slug, p_squad_id, 'discussion', new_id::text,
          jsonb_build_object('visibility', p_visibility));

  return new_id;
end $$;

grant execute on function public.create_discussion(text, text[], text, text, uuid) to authenticated;

-- Replies: rate-limited too, but far less strictly. A discussion that nobody
-- can answer is not a discussion (§51 "meaningful discussion").
create or replace function public.reply_rate_limit()
returns int language sql stable as $$
  select 20
$$;

create or replace function public.create_discussion_reply(p_discussion_id uuid, p_body_md text)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  recent int;
  new_id uuid;
begin
  if me is null then
    raise exception 'Log in to reply.';
  end if;

  if not exists (
    select 1 from public.discussions d
    where d.id = p_discussion_id and d.deleted_at is null
  ) then
    raise exception 'That discussion is gone.';
  end if;

  select count(*) into recent
  from public.discussion_replies r
  where r.author_id = me and r.deleted_at is null
    and r.created_at > now() - interval '10 minutes';
  if recent >= public.reply_rate_limit() then
    raise exception 'Slow down a little.';
  end if;

  insert into public.discussion_replies (discussion_id, author_id, body_md)
  values (p_discussion_id, me, p_body_md)
  returning id into new_id;

  return new_id;
end $$;

grant execute on function public.create_discussion_reply(uuid, text) to authenticated;